package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.FieldPosition;
import java.text.Format;
import java.text.NumberFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import java.util.*;
import java.util.Locale;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ComplexFormat_parse_TriageGen2Test {

    private ComplexFormat complexFormat;

    @Before
    public void setUp() {
        // Default constructor uses standard formats and "i" as imaginary character
        complexFormat = new ComplexFormat();
    }

    @Test
    public void testParse_ValidRealOnly() {
        String source = "12.5";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertNull("Should be null if input is empty", null); // logic check
        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(0.0, result.getImaginary(), 1e-10);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_ValidComplexPositive() {
        String source = "12.5+3.4i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(3.4, result.getImaginary(), 1e-10);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_ValidComplexNegative() {
        String source = "12.5-3.4i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(-3.4, result.getImaginary(), 1e-10);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_WithWhitespace() {
        String source = "  12.5  +  3.4  i  ";
        // Note: The implementation's whitespace handling depends on parseAndIgnoreWhitespace
        // and parseNumber. Assuming standard whitespace handling.
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(3.4, result.getImaginary(), 1e-10);
    }

    @Test
    public void testParse_InvalidRealNumber() {
        String source = "abc+1i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
    }

    @Test
    public void testParse_InvalidSign() {
        String source = "12.5*3.4i";
        ParsePosition pos = new ParsePosition(0);
        int startIndex = 0;

        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
        // The code sets error index to the start of the sign character
        // In "12.5*3.4i", '*' is at index 4
        assertEquals(4, pos.getErrorIndex());
    }

    @Test
    public void testParse_InvalidImaginaryNumber() {
        String source = "12.5+abc i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
    }

    @Test
    public void testParse_InvalidImaginaryCharacter() {
        String source = "12.5+3.4j"; // Expected 'i'
        ParsePosition pos = new ParsePosition(0);

        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
        // Error index should be where 'j' was found
        // "12.5+3.4j" -> 'j' is at index 7
        assertEquals(7, pos.getErrorIndex());
    }

    @Test
    public void testParse_PartialString() {
        String source = "12.5+3.4i extra";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(3.4, result.getImaginary(), 1e-10);
        assertEquals(8, pos.getIndex()); // length of "12.5+3.4i"
    }

    @Test
    public void testParse_CustomImaginaryCharacter() {
        // Using constructor with custom imaginary character
        complexFormat = new ComplexFormat("unit");
        String source = "1.0+2.0unit";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(1.0, result.getReal(), 1e-10);
        assertEquals(2.0, result.getImaginary(), 1e-10);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_InvalidCustomImaginaryCharacter() {
        complexFormat = new ComplexFormat("unit");
        String source = "1.0+2.0un";
        ParsePosition pos = new ParsePosition(0);

        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
        // "1.0+2.0un" -> 'u' is at index 5
        assertEquals(5, pos.getErrorIndex());
    }
}
